mapper.select:
-- 使用递归 CTE 生成还款日期序列并计算总还款金额 WITH RECURSIVE payment_days AS ( -- 计算第一个还款日期 SELECT s.id, s.sub_amount, s.end_date, -- 用变量简化处理 @new_start_date :=
CASE WHEN DATE_FORMAT( s.start_date, '%Y-%m-%d %H:%i:%s' ) < #{startDay} THEN STR_TO_DATE( #{startDay}, '%Y-%m-%d %H:%i:%s' ) ELSE s.start_date END AS new_start_date,
s.start_date AS new_start_date,
CASE WHEN DAY ( @new_start_date ) < s.payment_date THEN DATE_FORMAT( DATE ( @new_start_date )+ INTERVAL ( s.payment_date - DAY ( @new_start_date )) DAY, '%Y-%m-%d' ) ELSE DATE_FORMAT( DATE ( DATE_FORMAT( @new_start_date, '%Y-%m-01' ))+ INTERVAL 1 MONTH + INTERVAL ( s.payment_date - 1 ) DAY, '%Y-%m-%d' ) END AS payment_day FROM t_subscribe s
and s.id = #{id}
UNION ALL -- 递归部分，生成后续的还款日期 SELECT pd.id, pd.sub_amount, pd.end_date, '' AS new_start_date, DATE_FORMAT( STR_TO_DATE( pd.payment_day, '%Y-%m-%d' ) + INTERVAL 1 MONTH, '%Y-%m-%d' ) FROM payment_days pd WHERE pd.end_date > STR_TO_DATE(pd.payment_day, '%Y-%m-%d')
-- 递归终止条件：还款日期不超过指定日期 and STR_TO_DATE( pd.payment_day, '%Y-%m-%d %H:%i:%s' ) < #{endDay}
) -- 计算总还款金额 SELECT SUM( pd.sub_amount ) AS subMoneyCount FROM payment_days pd

SELECT sum(amount) FROM t_money


